<script lang="ts">let {data,form}=$props();</script><h1>Přijmout pozvánku</h1><p>Token obdržíte od správce bezpečným kanálem.</p>{#if form?.error}<p class="error">{form.error}</p>{/if}<form method="POST"><input type="hidden" name="csrf" value={data.csrf}/><label>Token pozvánky<input name="token" required autocomplete="off"/></label><label>Nové heslo, nejméně 14 znaků<input type="password" name="password" minlength="14" maxlength="256" autocomplete="new-password" required/></label><button>Vytvořit účet</button></form>
